package glitch

import data.glitch_lib

sensitive_keywords := {"password", "secret", "apikey", "token", "key", "credential", "auth", "passwd"}

check_attribute_name(name) {
    name.ir_type == "String"
    parts := split(name.value, ".")
    last_part := parts[count(parts) - 1]
    lower(last_part) in sensitive_keywords
} else {
    name.ir_type == "VariableReference"
    contains(name.value, "password")
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    check_attribute_name(attr.name)

    attr.value.ir_type == "String"
    not glitch_lib.traverse_var(attr.value)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Hard-coded credential found in IaC script (CWE-798)"
    }
}

